import sys

def main():
    data = sys.stdin.read().split()
    n, q = int(data[0]), int(data[1])
    a = list(map(int, data[2:2 + n]))
    qs = list(map(int, data[2 + n:2 + n + q]))
    cp = {}
    cur = 0
    for v in a:
        if v > cur:
            cur = v
        cp[cur] = cp.get(cur, 0) + 1
    cs = {}
    cur = 10**18
    for i in range(n - 1, -1, -1):
        if a[i] < cur:
            cur = a[i]
        cs[cur] = cs.get(cur, 0) + 1
    prod = {}
    for p, c1 in cp.items():
        for s, c2 in cs.items():
            k = p * s
            prod[k] = prod.get(k, 0) + c1 * c2
    print(' '.join(str(prod.get(x, 0)) for x in qs))

main()

